SELECT city, COUNT(*) AS sample_count, CORR(temperature_2m, pm2_5) AS corr_temp_pm25, CORR(relative_humidity_2m, pm2_5) AS corr_humidity_pm25, CORR(wind_speed_10m, pm2_5) AS corr_wind_pm25 FROM weather_airquality_records WHERE year='2026' AND month='10' AND day IN ('11','12','13','14','15','16','17','18') AND timestamp_utc >= '2026-10-11 17:00:00' AND timestamp_utc < '2026-10-18 17:00:00' GROUP BY city ORDER BY city;
